import re

def word_count(text: str) -> dict:
    """Count words case-insensitively, ignoring punctuation 
    word_count("Hi, hi! Bye.") -> {"hi": 2, "bye": 1}"""

    if not text:
        return {}

    text = re.sub(r'[^\w\s]', '', text.lower())
    words = text.split()
    word_counts = {}

    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    return word_counts
```
